window.CODE = Object.assign(window.CODE || {}, {"ch40/cost_model.py":"\"\"\"What does a coding-agent session cost, and why? A small model you can change and re-run.\n\nEvery turn an agent sends the WHOLE conversation again (system prompt, tool list, instruction\nfiles, everything said so far). Prompt caching makes the unchanged beginning cheap to resend.\nThis model turns that into numbers so you can see which habit saves the most.\n\nModel, in plain words\n  turn 1:   the starting context is written to the cache       -> costs 1.25x the normal input price\n  turn n:   the earlier context is read from the cache         -> costs 0.1x or less (per model)\n            this turn's NEW tokens (tool results) are written  -> 1.25x\n            the model's reply is billed at the output price\n  idle gap longer than the cache lifetime -> the next turn cannot read the cache and writes it all again.\n\nSimplifications (it is a teaching model, not an invoice): 5-minute cache writes only; one price\ntier; no thinking tokens (they are billed as output, so real sessions cost more); no\nlong-prompt surcharge; list prices from prices.json (read 5 Nov 2026).\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nfrom dataclasses import dataclass\nfrom pathlib import Path\n\nPRICES = json.loads((Path(__file__).with_name(\"prices.json\")).read_text())\n\n\n@dataclass\nclass Session:\n    model: str = \"sonnet-5.5\"\n    start_context: int = 20_000         # system prompt + tools + CLAUDE.md etc. carried from turn 1\n    turns: int = 30\n    new_per_turn: int = 3_000           # tokens of tool results / file reads added each turn\n    output_per_turn: int = 800\n    caching: bool = True\n    clear_at: tuple = ()                # turns after which the user runs /clear (context drops to start_context)\n    idle_gaps: tuple = ()               # turns that follow a pause longer than the cache lifetime\n\n\ndef cost(s: Session) -> dict:\n    m = PRICES[\"models\"][s.model]\n    p_in, p_out = m[\"input\"] / 1e6, m[\"output\"] / 1e6\n    p_read = p_in * m[\"cache_read_multiplier\"]\n    p_write = p_in * PRICES[\"cache_write_5m_multiplier\"]\n    ctx = s.start_context\n    cached = 0                          # how much of the context is currently in the cache\n    parts = {\"cache_write\": 0.0, \"cache_read\": 0.0, \"plain_input\": 0.0, \"output\": 0.0}\n    for t in range(1, s.turns + 1):\n        if t > 1:\n            ctx += s.new_per_turn\n        if (t - 1) in s.clear_at:\n            ctx = s.start_context + s.new_per_turn\n            cached = min(cached, s.start_context)         # the shared beginning (system prompt, tools, CLAUDE.md) is still cached\n        if t in s.idle_gaps:\n            cached = 0\n        if s.caching:\n            parts[\"cache_read\"] += cached * p_read\n            parts[\"cache_write\"] += (ctx - cached) * p_write\n            cached = ctx\n        else:\n            parts[\"plain_input\"] += ctx * p_in\n        parts[\"output\"] += s.output_per_turn * p_out\n    parts[\"total\"] = sum(parts.values())\n    return {k: round(v, 4) for k, v in parts.items()}\n\n\ndef compare(label_to_session: dict) -> str:\n    rows = [(label, cost(s)[\"total\"]) for label, s in label_to_session.items()]\n    base = rows[0][1]\n    return \"\\n\".join(f\"{label:<44} ${c:>7.2f}  ({c / base:>4.0%} of the first row)\" for label, c in rows)\n\n\nif __name__ == \"__main__\":\n    base = Session()\n    print(compare({\n        \"baseline: Sonnet, 20k start, 30 turns, cached\": base,\n        \"same, but caching is not used\": Session(caching=False),\n        \"same, CLAUDE.md trimmed (start 12k, not 20k)\": Session(start_context=12_000),\n        \"same, one 10-minute break at turn 16\": Session(idle_gaps=(16,)),\n        \"same, on Opus 5.5\": Session(model=\"opus-5.5\"),\n        \"same, on Haiku 5.5\": Session(model=\"haiku-5.5\"),\n    }))\n    print()\n    print(compare({\n        \"two tasks in ONE 60-turn session\": Session(turns=60),\n        \"two tasks, /clear between them (at turn 30)\": Session(turns=60, clear_at=(30,)),\n    }))\n","ch40/ctx_budget.py":"\"\"\"Where would the tokens go if an agent read this repository? A quick, offline budget.\n\n    python ctx_budget.py ../ch27            # biggest files and the total\n    python ctx_budget.py ../ch27 --top 5\n\nHONEST LIMITS. Tokens are counted with a rule of thumb (about 4 characters per token for English\nprose, about 3.5 for code). Each vendor's real tokenizer gives a different number, so treat the\nresult as \"within about 25%\", good for finding the big spenders, not for billing. For exact\nnumbers, ask the provider's token-counting API or read the usage fields in a real response.\n\"\"\"\nfrom __future__ import annotations\n\nimport fnmatch\nimport sys\nfrom dataclasses import dataclass\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent / \"ch38\"))\nimport agent_files  # noqa: E402  (which instruction files exist; they are paid for on EVERY request)\n\nDEFAULT_IGNORE = [\".git\", \"node_modules\", \"__pycache__\", \".venv\", \"venv\", \"dist\", \"build\", \".pytest_cache\",\n                  \"*.lock\", \"package-lock.json\", \"*.min.js\", \"*.map\", \"*.pyc\", \"*.png\", \"*.jpg\", \"*.zip\", \"*.jsonl\", \"*.sqlite\", \"*.db\"]\nCODE_SUFFIXES = {\".py\", \".js\", \".ts\", \".java\", \".go\", \".rs\", \".c\", \".cpp\", \".json\", \".yaml\", \".yml\", \".toml\", \".sh\"}\n\n\ndef estimate_tokens(text: str, suffix: str = \"\") -> int:\n    per = 3.5 if suffix in CODE_SUFFIXES else 4.0\n    return round(len(text) / per)\n\n\n@dataclass\nclass FileCost:\n    path: str\n    tokens: int\n\n\ndef ignored(rel: Path, patterns: list[str]) -> bool:\n    return any(fnmatch.fnmatch(part, pat) for part in rel.parts for pat in patterns)\n\n\ndef scan(root: str | Path, ignore: list[str] | None = None) -> list[FileCost]:\n    root = Path(root)\n    patterns = DEFAULT_IGNORE if ignore is None else ignore\n    out = []\n    for p in sorted(root.rglob(\"*\")):\n        rel = p.relative_to(root)\n        if not p.is_file() or ignored(rel, patterns):\n            continue\n        try:\n            text = p.read_text()\n        except (UnicodeDecodeError, OSError):\n            continue                       # binary: an agent would not read it as text either\n        out.append(FileCost(rel.as_posix(), estimate_tokens(text, p.suffix)))\n    return sorted(out, key=lambda f: -f.tokens)\n\n\ndef instruction_overhead(root: str | Path) -> int:\n    \"\"\"Tokens of the instruction files an agent loads at the start and carries in every request.\"\"\"\n    root = Path(root)\n    total = 0\n    for f in agent_files.claude_reads(root):\n        text = (root / f).read_text(errors=\"replace\")\n        if f.startswith(\".claude/rules/\") and text.startswith(\"---\") and \"paths:\" in text.split(\"---\")[1]:\n            continue                       # a path-scoped rule is loaded only when the agent touches a matching file\n        total += estimate_tokens(text, \".md\")\n    return total\n\n\ndef report(root: str | Path, top: int = 8) -> str:\n    files = scan(root)\n    total = sum(f.tokens for f in files)\n    lines = [f\"{len(files)} text files, about {total:,} tokens if an agent read all of them (it should not).\", \"\"]\n    lines += [f\"  {f.tokens:>7,}  {f.path}\" for f in files[:top]]\n    if len(files) > top:\n        lines.append(f\"  ... and {len(files) - top} smaller files\")\n    inst = instruction_overhead(root)\n    lines += [\"\", f\"Instruction files carried in every request: about {inst:,} tokens\"]\n    return \"\\n\".join(lines)\n\n\nif __name__ == \"__main__\":\n    a = sys.argv[1:]\n    top = int(a[a.index(\"--top\") + 1]) if \"--top\" in a else 8\n    print(report(a[0] if a and not a[0].startswith(\"--\") else \".\", top))\n","ch40/demo_filter.py":"\"\"\"Measure what output_filter saves on REAL pytest output from the helpdesk.\n\nCopies the Chapter 27 helpdesk to a temp folder, runs its tests (a) as they are and (b) after we break\none rule on purpose, and prints how many tokens (estimated, ~3.5 chars each) the agent would read\nwith and without the filter.   Run:  python demo_filter.py\n\"\"\"\nimport re\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\nfrom pathlib import Path\n\nfrom ctx_budget import estimate_tokens\nfrom output_filter import grep_style, pytest_style\n\nSAMPLES = Path(__file__).resolve().parent.parent\nNEEDED = [\"ch07\", \"ch09\", \"ch16\", \"ch21\", \"ch27\", \"ch34\", \"ch38\", \"ch39\"]       # the helpdesk and the folders it imports from\n\n\ndef pytest_output(folder, *flags):\n    p = subprocess.run([sys.executable, \"-m\", \"pytest\", *flags], cwd=folder, capture_output=True, text=True)\n    return p.stdout + p.stderr\n\n\nwith tempfile.TemporaryDirectory() as tmp:\n    root = Path(tmp) / \"code-samples\"\n    for name in NEEDED:\n        shutil.copytree(SAMPLES / name, root / name, ignore=shutil.ignore_patterns(\"__pycache__\", \".pytest_cache\"))\n    work = root / \"ch27\"\n    rows = []\n    for label, flags in [(\"helpdesk, passing, -q\", [\"-q\"]), (\"helpdesk, passing, -v\", [\"-v\"])]:\n        raw = pytest_output(work, *flags)\n        rows.append((label, raw))\n    raw = pytest_output(root, \"-v\", \"ch27\", \"ch38\", \"ch39\")\n    rows.append((\"3 folders (~40 tests), passing, -v\", raw))\n    cfg = work / \"config.py\"\n    cfg.write_text(re.sub(r\"MAX_REPLY_WORDS = \\d+\", \"MAX_REPLY_WORDS = 3\", cfg.read_text()))   # break a rule on purpose\n    for label, flags in [(\"helpdesk, 1 rule broken, -q\", [\"-q\"]), (\"helpdesk, 1 rule broken, -v\", [\"-v\"])]:\n        raw = pytest_output(work, *flags)\n        rows.append((label, raw))\n\nprint(f\"{'run':<36}{'raw':>6}   {'grep-style':>11}   {'pytest-style':>12}   keeps the 'E' reason?\")\nfor label, raw in rows:\n    g, p = grep_style(raw), pytest_style(raw)\n    has_reason = \"E   \" in raw\n    print(f\"{label:<36}{estimate_tokens(raw):>6}   {estimate_tokens(g):>11}   {estimate_tokens(p):>12}   \"\n          + (\"(no failure)\" if not has_reason else f\"grep: {'yes' if 'E   ' in g else 'NO '}  pytest: {'yes' if 'E   ' in p else 'NO'}\"))\nprint(\"\\nTokens are estimates (~3.5 characters each).\")\n","ch40/hooks/filter_test_command.py":"#!/usr/bin/env python3\n\"\"\"A Claude Code PreToolUse hook that rewrites plain test commands so only the useful lines come back.\n\nRegister it in .claude/settings.json (see settings.example.json). Claude Code runs it before each Bash\ntool call and sends JSON on stdin; the hook may answer with JSON on stdout. The contract below is from\ncode.claude.com/docs/en/hooks and /costs (read 5 Nov 2026):\n  stdin : {\"hook_event_name\": \"PreToolUse\", \"tool_name\": \"Bash\", \"tool_input\": {\"command\": \"...\"}, ...}\n  stdout: {\"hookSpecificOutput\": {\"hookEventName\": \"PreToolUse\", \"updatedInput\": {...}}}   to change the call\n          {}                                                                                to leave it alone\n\nTwo changes from the example on the costs page, both found by testing it (see test_ch40.py):\n  1. `cmd | grep | head` returns head's exit status, so a failing test run looks like success. We add\n     `set -o pipefail` so the test runner's own exit code survives.\n  2. The grep filter can drop the line that says why a test failed, so we pipe to output_filter.py.\nOnly a plain test command is touched; anything with pipes, ';', '&&' or redirects is left alone.\n\"\"\"\nimport json\nimport os\nimport re\nimport shlex\nimport sys\n\nSAFE = re.compile(r\"^(npm test|pytest|python3? -m pytest|go test)( [^;&|<>`$#\\\\\\n]*)?$\")\nFILTER = os.path.join(os.path.dirname(os.path.abspath(__file__)), \"output_filter.py\")\n\n\ndef rewrite(command: str):\n    if not SAFE.match(command):\n        return None\n    return f\"set -o pipefail; {command} 2>&1 | python3 {shlex.quote(FILTER)}\"\n\n\ndef main():\n    event = json.load(sys.stdin)\n    cmd = (event.get(\"tool_input\") or {}).get(\"command\", \"\")\n    new = rewrite(cmd) if event.get(\"tool_name\") == \"Bash\" else None\n    if new is None:\n        print(\"{}\")\n        return\n    updated = dict(event[\"tool_input\"], command=new)\n    print(json.dumps({\"hookSpecificOutput\": {\"hookEventName\": \"PreToolUse\", \"updatedInput\": updated}}))\n\n\nif __name__ == \"__main__\":\n    main()\n","ch40/hooks/output_filter.py":"\"\"\"Cut test output down to what the agent needs BEFORE it reads it.\n\nA big test run prints hundreds of lines. Two filters, so you can compare them:\n\n  grep_style    the pattern from the Claude Code costs page (read 5 Nov 2026):\n                    <cmd> 2>&1 | grep -A 5 -E '(FAIL|ERROR|error:)' | head -100\n                 ported to Python. Simple, but see the demo: on pytest it can drop the line\n                that says WHY a test failed.\n  pytest_style  keeps what a person fixing a failure reads: the failure header, the line marked\n                '>' (the failing statement), the lines marked 'E' (the reason), the FAILED/ERROR\n                summary lines, and the final count.\n\n    python -m pytest 2>&1 | python output_filter.py           # pytest_style\n    python -m pytest 2>&1 | python output_filter.py --grep    # the documented grep-style\n\"\"\"\nfrom __future__ import annotations\n\nimport re\nimport sys\n\nGREP_PATTERN = re.compile(r\"(FAIL|ERROR|error:)\")\n\n\ndef grep_style(text: str, after: int = 5, limit: int = 100) -> str:\n    keep, remaining = [], 0\n    for line in text.splitlines():\n        if GREP_PATTERN.search(line):\n            remaining = after\n            keep.append(line)\n        elif remaining > 0:\n            keep.append(line)\n            remaining -= 1\n    return \"\\n\".join(keep[:limit])\n\n\ndef pytest_style(text: str, limit: int = 80) -> str:\n    lines = text.splitlines()\n    keep = []\n    for line in lines:\n        if (re.match(r\"^_{3,} .+ _{3,}$\", line) or line.startswith(\">\") or re.match(r\"^E( |$)\", line)\n                or line.startswith((\"FAILED\", \"ERROR\")) or re.match(r\"^=+ .*(FAILURES|ERRORS).* =+$\", line)):\n            keep.append(line)\n    summary = [l for l in lines if re.search(r\"\\b\\d+ (passed|failed|error)\", l)][-1:]      # \"2 failed, 14 passed in 1.5s\"\n    return \"\\n\".join((keep[:limit] + summary) if keep or summary else lines[-3:])\n\n\nif __name__ == \"__main__\":\n    data = sys.stdin.read()\n    sys.stdout.write((grep_style(data) if \"--grep\" in sys.argv else pytest_style(data)) + \"\\n\")\n","ch40/hooks/settings.example.json":"{\n  \"hooks\": {\n    \"PreToolUse\": [\n      {\n        \"matcher\": \"Bash\",\n        \"hooks\": [\n          { \"type\": \"command\", \"command\": \"python3 \\\"$CLAUDE_PROJECT_DIR\\\"/.claude/hooks/filter_test_command.py\" }\n        ]\n      }\n    ]\n  }\n}\n","ch40/output_filter.py":"\"\"\"Cut test output down to what the agent needs BEFORE it reads it.\n\nA big test run prints hundreds of lines. Two filters, so you can compare them:\n\n  grep_style    the pattern from the Claude Code costs page (read 5 Nov 2026):\n                    <cmd> 2>&1 | grep -A 5 -E '(FAIL|ERROR|error:)' | head -100\n                 ported to Python. Simple, but see the demo: on pytest it can drop the line\n                that says WHY a test failed.\n  pytest_style  keeps what a person fixing a failure reads: the failure header, the line marked\n                '>' (the failing statement), the lines marked 'E' (the reason), the FAILED/ERROR\n                summary lines, and the final count.\n\n    python -m pytest 2>&1 | python output_filter.py           # pytest_style\n    python -m pytest 2>&1 | python output_filter.py --grep    # the documented grep-style\n\"\"\"\nfrom __future__ import annotations\n\nimport re\nimport sys\n\nGREP_PATTERN = re.compile(r\"(FAIL|ERROR|error:)\")\n\n\ndef grep_style(text: str, after: int = 5, limit: int = 100) -> str:\n    keep, remaining = [], 0\n    for line in text.splitlines():\n        if GREP_PATTERN.search(line):\n            remaining = after\n            keep.append(line)\n        elif remaining > 0:\n            keep.append(line)\n            remaining -= 1\n    return \"\\n\".join(keep[:limit])\n\n\ndef pytest_style(text: str, limit: int = 80) -> str:\n    lines = text.splitlines()\n    keep = []\n    for line in lines:\n        if (re.match(r\"^_{3,} .+ _{3,}$\", line) or line.startswith(\">\") or re.match(r\"^E( |$)\", line)\n                or line.startswith((\"FAILED\", \"ERROR\")) or re.match(r\"^=+ .*(FAILURES|ERRORS).* =+$\", line)):\n            keep.append(line)\n    summary = [l for l in lines if re.search(r\"\\b\\d+ (passed|failed|error)\", l)][-1:]      # \"2 failed, 14 passed in 1.5s\"\n    return \"\\n\".join((keep[:limit] + summary) if keep or summary else lines[-3:])\n\n\nif __name__ == \"__main__\":\n    data = sys.stdin.read()\n    sys.stdout.write((grep_style(data) if \"--grep\" in sys.argv else pytest_style(data)) + \"\\n\")\n","ch40/prices.json":"{\n  \"_source\": \"platform.claude.com/docs/en/about-claude/pricing, read on 5 Nov 2026. USD per million tokens. Prices change: check claude.com/pricing before you plan anything. These are API list prices; a subscription plan is billed differently.\",\n  \"cache_write_5m_multiplier\": 1.25,\n  \"cache_write_1h_multiplier\": 2.0,\n  \"models\": {\n    \"haiku-5.5\":  {\"input\": 0.10, \"output\": 0.50,  \"cache_read_multiplier\": 0.1,   \"note\": \"prompts over 100K tokens pay input 0.50 / output 2.50 for the whole request (not modelled here)\"},\n    \"sonnet-5.5\": {\"input\": 2.00, \"output\": 10.00, \"cache_read_multiplier\": 0.05},\n    \"opus-5.5\":   {\"input\": 4.00, \"output\": 20.00, \"cache_read_multiplier\": 0.05},\n    \"fable-5.1\":  {\"input\": 10.00, \"output\": 50.00, \"cache_read_multiplier\": 0.025}\n  }\n}\n","ch40/README.md":"# Chapter 40 · Saving tokens and cost\n\n| file | what it is |\n| --- | --- |\n| `ctx_budget.py` | estimates the tokens in each file of a repository, and the instruction files carried in every request |\n| `prices.json` | list prices read from Anthropic's pricing page on 5 Nov 2026. **Check before you rely on them.** |\n| `cost_model.py` | a teaching model of a session's cost with and without prompt caching, `/clear`, idle gaps and model choice |\n| `output_filter.py` | two ways to shrink test output, and which one keeps the reason a test failed |\n| `hooks/filter_test_command.py` | a Claude Code PreToolUse hook using that filter; `settings.example.json` registers it |\n| `demo_filter.py` | measures the filters on real pytest output from the helpdesk |\n\n    python -m pytest -q       # 19 tests; needs bash\n    python cost_model.py\n    python demo_filter.py\n\nToken counts here are estimates (about 3.5 to 4 characters per token). The hook is tested by feeding it the JSON the\ndocumentation describes; it has not been run inside a real Claude Code session.\n","ch40/test_ch40.py":"import json\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nimport pytest\n\nimport cost_model as cm\nimport ctx_budget as cb\nimport output_filter as of\n\nHERE = Path(__file__).resolve().parent\nHOOK = HERE / \"hooks\" / \"filter_test_command.py\"\n\nFAILING_LOG = \"\"\"============================= test session starts ==============================\ncollected 3 items\n\ntest_a.py .F.                                                            [100%]\n\n=================================== FAILURES ===================================\n____________________________ test_fee_is_correct _______________________________\n\n    def test_fee_is_correct():\n        fee = compute_fee(\"ECG\")\n>       assert fee == 350\nE       assert 300 == 350\n\ntest_a.py:4: AssertionError\n=========================== short test summary info ============================\nFAILED test_a.py::test_fee_is_correct - assert 300 == 350\n========================= 1 failed, 2 passed in 0.12s ==========================\n\"\"\"\nPASSING_LOG = \"...                                                                      [100%]\\n3 passed in 0.02s\\n\"\n\n\n# ---------- token estimates and the repo scan ----------\ndef test_estimate_tokens_rule_of_thumb():\n    assert cb.estimate_tokens(\"a\" * 400) == 100\n    assert cb.estimate_tokens(\"a\" * 350, \".py\") == 100\n\n\ndef test_scan_ignores_junk_and_sorts_by_size(tmp_path):\n    (tmp_path / \"big.py\").write_text(\"x = 1\\n\" * 500)\n    (tmp_path / \"small.py\").write_text(\"x = 1\\n\")\n    (tmp_path / \"node_modules\").mkdir()\n    (tmp_path / \"node_modules\" / \"huge.js\").write_text(\"y\" * 100000)\n    (tmp_path / \"data.jsonl\").write_text(\"z\" * 100000)\n    (tmp_path / \"pic.png\").write_bytes(b\"\\x89PNG\\xff\\xfe\\x00\")\n    names = [f.path for f in cb.scan(tmp_path)]\n    assert names == [\"big.py\", \"small.py\"]\n\n\ndef test_instruction_overhead_counts_imported_files():\n    starter = HERE.parent / \"ch39\" / \"starter\"\n    names = {f.path: f.tokens for f in cb.scan(starter)}\n    # CLAUDE.md plus the AGENTS.md it imports; the path-scoped rules file is NOT carried in every request\n    assert cb.instruction_overhead(starter) == names[\"CLAUDE.md\"] + names[\"AGENTS.md\"]\n    assert \"Instruction files carried in every request\" in cb.report(starter)\n\n\n# ---------- the cost model ----------\ndef test_cost_matches_a_hand_calculation():\n    s = cm.Session(model=\"sonnet-5.5\", start_context=1000, turns=2, new_per_turn=500, output_per_turn=100)\n    # turn 1: write 1000 at 2.50/M + out 100 at 10/M ; turn 2: read 1000 at 0.10/M + write 500 at 2.50/M + out\n    expected = (1000 * 2.5 + 100 * 10 + 1000 * 0.1 + 500 * 2.5 + 100 * 10) / 1e6\n    assert cm.cost(s)[\"total\"] == pytest.approx(expected, abs=1e-4)\n\n\ndef test_caching_makes_a_long_session_much_cheaper():\n    assert cm.cost(cm.Session(caching=False))[\"total\"] > 4 * cm.cost(cm.Session())[\"total\"]\n\n\ndef test_smaller_start_clear_and_idle_gap_effects():\n    base = cm.cost(cm.Session())[\"total\"]\n    assert cm.cost(cm.Session(start_context=12_000))[\"total\"] < base\n    assert cm.cost(cm.Session(idle_gaps=(16,)))[\"total\"] > base\n    assert cm.cost(cm.Session(turns=60, clear_at=(30,)))[\"total\"] < cm.cost(cm.Session(turns=60))[\"total\"]\n\n\ndef test_model_order_and_price_file():\n    totals = [cm.cost(cm.Session(model=m))[\"total\"] for m in (\"haiku-5.5\", \"sonnet-5.5\", \"opus-5.5\", \"fable-5.1\")]\n    assert totals == sorted(totals)\n    assert cm.PRICES[\"cache_write_5m_multiplier\"] == 1.25 and cm.PRICES[\"models\"][\"sonnet-5.5\"][\"cache_read_multiplier\"] == 0.05\n\n\n# ---------- the filters ----------\ndef test_grep_style_drops_the_reason_and_pytest_style_keeps_it():\n    g, p = of.grep_style(FAILING_LOG), of.pytest_style(FAILING_LOG)\n    assert \"E       assert 300 == 350\" not in g\n    assert \"E       assert 300 == 350\" in p and \"1 failed, 2 passed\" in p\n    assert len(p) < len(FAILING_LOG)\n\n\ndef test_grep_style_is_silent_on_success_but_pytest_style_says_so():\n    assert of.grep_style(PASSING_LOG) == \"\"\n    assert of.pytest_style(PASSING_LOG) == \"3 passed in 0.02s\"\n\n\n# ---------- the hook, spoken to exactly as Claude Code would ----------\ndef call_hook(event):\n    r = subprocess.run([sys.executable, str(HOOK)], input=json.dumps(event), capture_output=True, text=True)\n    assert r.returncode == 0, r.stderr\n    return json.loads(r.stdout)\n\n\ndef bash_event(cmd):\n    return {\"hook_event_name\": \"PreToolUse\", \"tool_name\": \"Bash\", \"tool_input\": {\"command\": cmd, \"description\": \"run tests\"}}\n\n\ndef test_hook_rewrites_a_plain_test_command_and_keeps_other_fields():\n    out = call_hook(bash_event(\"pytest -q\"))[\"hookSpecificOutput\"]\n    assert out[\"hookEventName\"] == \"PreToolUse\"\n    assert out[\"updatedInput\"][\"command\"].startswith(\"set -o pipefail; pytest -q 2>&1 | python3 \")\n    assert out[\"updatedInput\"][\"description\"] == \"run tests\"\n\n\n@pytest.mark.parametrize(\"cmd\", [\"pytest | tee log.txt\", \"pytest; rm -rf /\", \"pytest && echo hi\", \"ls -la\", \"pytest $(whoami)\", \"pytest > out.txt\"])\ndef test_hook_leaves_other_commands_alone(cmd):\n    assert call_hook(bash_event(cmd)) == {}\n\n\ndef test_hook_ignores_other_tools():\n    assert call_hook({\"hook_event_name\": \"PreToolUse\", \"tool_name\": \"Read\", \"tool_input\": {\"file_path\": \"x\"}}) == {}\n\n\ndef run_bash(cmd, cwd):\n    return subprocess.run([\"bash\", \"-c\", cmd], cwd=cwd, capture_output=True, text=True)\n\n\ndef test_rewritten_command_keeps_exit_code_and_the_reason(tmp_path):\n    (tmp_path / \"test_x.py\").write_text(\"def test_bad():\\n    assert 1 + 1 == 3\\n\")\n    cmd = call_hook(bash_event(\"python3 -m pytest -q\"))[\"hookSpecificOutput\"][\"updatedInput\"][\"command\"]\n    bad = run_bash(cmd, tmp_path)\n    assert bad.returncode != 0 and \"assert\" in bad.stdout and \"1 failed\" in bad.stdout\n    (tmp_path / \"test_x.py\").write_text(\"def test_ok():\\n    assert 1 + 1 == 2\\n\")\n    good = run_bash(cmd, tmp_path)\n    assert good.returncode == 0 and \"1 passed\" in good.stdout\n\n\ndef test_the_documented_grep_pipeline_loses_the_exit_code():\n    # `false` stands in for a failing test run: the pipeline still reports success because `head` is last.\n    assert run_bash(\"false 2>&1 | grep -A 5 -E '(FAIL|ERROR|error:)' | head -100\", \".\").returncode == 0\n    assert run_bash(\"set -o pipefail; false 2>&1 | python3 -c 'import sys; sys.stdin.read()'\", \".\").returncode == 1\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
